mapper.update:
UPDATE item_post
SET status = 'SEARCHING', published_at = CURRENT_TIMESTAMP, updated_by = #{publisherId}
WHERE id = #{id} AND publisher_id = #{publisherId}
  AND deleted = 0 AND status = 'DRAFT'

UPDATE item_post
SET deleted = 1, status = 'REMOVED', updated_by = #{publisherId}
WHERE id = #{id} AND publisher_id = #{publisherId}
  AND deleted = 0 AND status IN ('DRAFT', 'SEARCHING')

UPDATE item_post
SET status = 'COMPLETED', completed_at = CURRENT_TIMESTAMP, updated_by = #{publisherId}
WHERE id = #{id} AND publisher_id = #{publisherId}
  AND deleted = 0 AND status = 'CLAIM_VERIFYING'
